 "content": "def transform(grid):
    """Replace background gaps in non-background row segments with 1."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        # A row is eligible when its non-background pattern is followed by
        # background gaps that form a continuation area; preserve its motif
        # and mark only the zero/background cells in that row's extension.
        positions = [c for c, v in enumerate(row) if v != bg]
        if not positions:
            continue
        # Fill only if the row's final non-background run starts a row-shaped
        # extension beyond an established patterned prefix.
        last = positions[-1]
        if last < len(row) - 1 and len(positions) >= 2:
            # Choose extension onset from the repeated 3-column motif unit.
            onset = ((last + 1 + 2) // 3) * 3
            if onset <= last:
                onset = last + 1
            for c in range(onset, len(row)):
                if row[c] == bg:
                    out[r][c] = 1
    return out

